  flex-wrap: nowrap;
  gap: 6px;
  white-space: nowrap;
}

.hint-display .ch {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  min-width: 22px;
  height: 32px;
  border-bottom: 2px solid var(--border-color);
