  transition: all 0.15s ease;
}

.hint-display .ch.blank {
  color: var(--text-muted);
  border-bottom-color: var(--border-color);
  opacity: 0.45;
}

.hint-display .ch.correct {
  color: var(--success);
  border-bottom-color: var(--success);
  font-weight: 600;
}

.hint-display .ch.incorrect {
  color: var(--error);
  border-bottom-color: var(--error);
}

.hint-display .ch.assisted {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.hint-display .ch.extra {
  color: var(--error);
  text-decoration: line-through;
  border-bottom: none;
}

.hint-display .ch.symbol {
  color: var(--text-muted);
  border-bottom: none;
}

.hint-display .ch.active-cursor {
  border-bottom-color: var(--accent);
  animation: apple-cursor 1s infinite;
}

@keyframes apple-cursor {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.hint-display .ch-space {
  display: inline-block;
  min-width: 16px;
  border-bottom: 2px solid transparent;
